<script setup lang="ts">
import {onMounted,onUnmounted,ref,watch} from 'vue'
import {useSession} from './session'
import {api} from './api'
const session=useSession(),phone=ref(''),code=ref(''),demoCode=ref(''),busy=ref(false),seconds=ref(0)
let timer:ReturnType<typeof setInterval>
const expired=()=>{session.user=null;session.loginOpen=true}
onMounted(()=>{session.restore();window.addEventListener('auth-expired',expired)})
onUnmounted(()=>{clearInterval(timer);window.removeEventListener('auth-expired',expired)})
async function send(){if(!/^1\d{10}$/.test(phone.value))return session.toast('请输入正确的 11 位手机号');busy.value=true;try{const data=await api<{demoCode?:string}|null>('/user/code?phone='+phone.value,'POST');demoCode.value=data?.demoCode||'';if(demoCode.value){code.value=demoCode.value;session.toast('演示验证码已填入，点击登录即可')}else{session.toast('验证码已生成，请查看服务日志')}seconds.value=60;clearInterval(timer);timer=setInterval(()=>{if(--seconds.value<=0)clearInterval(timer)},1000)}catch(e:any){session.toast(e.message)}finally{busy.value=false}}
watch(phone,()=>{demoCode.value='';code.value=''});
async function login(){busy.value=true;try{await session.login(phone.value,code.value)}catch(e:any){session.toast(e.message)}finally{busy.value=false}}
</script>
<template><header><RouterLink class="brand" to="/">巷遇<span>XIANGYU / CITY GUIDE</span></RouterLink><nav><RouterLink to="/">发现</RouterLink><RouterLink to="/shops">找店</RouterLink><RouterLink to="/notes">探店笔记</RouterLink><RouterLink to="/feed">关注动态</RouterLink></nav><RouterLink v-if="session.user" class="button secondary" to="/me">{{session.user.nickName||'我的空间'}}</RouterLink><button v-else @click="session.loginOpen=true">登录 / 注册</button></header><main><RouterView/></main><footer>巷遇 CITY GUIDE <span>让每一次出门，都有一点新发现。</span><RouterLink to="/write">写探店笔记 ↗</RouterLink></footer><div v-if="session.loginOpen" class="modal-wrap" @click.self="session.loginOpen=false"><section class="login-panel" role="dialog" aria-modal="true" aria-labelledby="login-title"><button class="close" @click="session.loginOpen=false" aria-label="关闭">×</button><p class="eyebrow">WELCOME TO XIANGYU</p><h2 id="login-title">发现好店，从这里开始</h2><p class="muted">手机号验证码登录，未注册用户将自动注册。</p><form @submit.prevent="login"><label for="phone">手机号码</label><input id="phone" v-model="phone" type="tel" maxlength="11" autocomplete="tel" required pattern="1[0-9]{10}" placeholder="请输入手机号码"><label for="code">验证码</label><div class="row no-wrap"><input id="code" v-model="code" required pattern="[0-9]{6}" maxlength="6" inputmode="numeric" autocomplete="one-time-code" placeholder="6 位验证码"><button type="button" class="secondary" :disabled="busy||seconds>0" @click="send">{{seconds?seconds+' 秒':'获取验证码'}}</button></div><p class="notice"><template v-if="demoCode">本地演示验证码：<strong>{{demoCode}}</strong>（2 分钟内有效，已自动填入）。未发送真实短信。</template><template v-else>当前为本地学习环境。点击获取验证码后，演示验证码会显示在这里。</template></p><button class="full" :disabled="busy">{{busy?'正在处理…':'登录 / 注册'}}</button></form></section></div><div v-if="session.message" class="toast" role="status">{{session.message}}</div></template>
